code.zh:
import sharp from 'sharp';

// upload：用户上传的字节，文件名和 MIME 类型都不参与判断
const thumb = await sharp(upload)  // ① 记录输入，此时还没有解码
  .resize(800)                     // ② 触发 shrink-on-load
  .webp()
  .toBuffer();                     // ③ 在工作线程里打开并解码

code.en:
import sharp from 'sharp';

// upload: bytes from the user; file name and MIME type are never consulted
const thumb = await sharp(upload)  // ① records the input, nothing decoded yet
  .resize(800)                     // ② enables shrink-on-load
  .webp()
  .toBuffer();                     // ③ opens and decodes on a worker thread

