code.zh:
import { readFile } from 'node:fs/promises';
import sharp from 'sharp';

// 文件名是 avatar.jpg，内容其实是 TIFF
const input = await readFile('uploads/avatar.jpg');
await sharp(input).resize(256).png().toBuffer();  // ① 选中的是 tiffload

code.en:
import { readFile } from 'node:fs/promises';
import sharp from 'sharp';

// named avatar.jpg, but the bytes are a TIFF
const input = await readFile('uploads/avatar.jpg');
await sharp(input).resize(256).png().toBuffer();  // ① tiffload is chosen

